<?php
namespace App\\Services;use Illuminate\\Support\\Facades\\DB;use Illuminate\\Support\\Str;use App\\Models\\Appointment;use App\\Models\\Reminder;use Symfony\\Component\\HttpKernel\\Exception\\BadRequestHttpException;
class InboundWebhookService{public function handle(array $d):void{DB::transaction(function()use($d){$insert=DB::table('inbound_messages')->insertOrIgnore(['message_id'=>$d['messageId'],'from_phone'=>$d['from'],'text'=>$d['text'],'received_at'=>$d['receivedAt'],'result'=>'received']);if(!$insert)return;$text=Str::upper(trim(preg_replace('/^[\\p{P}\\s]+|[\\p{P}\\s]+$/u','',Str::ascii($d['text']))));if(!in_array($text,['SI','NO'],true)){DB::table('inbound_messages')->where('message_id',$d['messageId'])->update(['result'=>'ignored']);return;}$rem=Reminder::where('status','sent')->where('delivered_to',$d['from'])->whereHas('appointment',fn($q)=>$q->where('starts_at','>',now())->where('status','!=','cancelled'))->orderByDesc('sent_at')->lockForUpdate()->first();if(!$rem){DB::table('inbound_messages')->where('message_id',$d['messageId'])->update(['result'=>'unmatched']);return;}$a=Appointment::whereKey($rem->appointment_id)->lockForUpdate()->first();if(!$a||$a->starts_at->isPast()||$a->status==='cancelled'){DB::table('inbound_messages')->where('message_id',$d['messageId'])->update(['result'=>'stale']);return;}if($text==='SI'){$a->status='confirmed';$a->save();}else{$a->status='cancelled';$a->save();Reminder::where('appointment_id',$a->id)->where('status','pending')->update(['status'=>'cancelled']);}DB::table('inbound_messages')->where('message_id',$d['messageId'])->update(['result'=>$text==='SI'?'confirmed':'cancelled']);});}}